    def show_popupVideo(self):
        msg0 = QMessageBox()
        msg0.setWindowTitle("Take video")
        msg0.setText("Wait for the camera to setup...")
        msg0.setIcon(QMessageBox.Information)


        x = msg0.exec_()

        [self.cap, self.camWidth, self.camHeight, self.camFPS, self.camfourcc] = startCam()
        
        msg1 = QMessageBox()
        msg1.setWindowTitle("Take video")
