    def pressed(self):
        self.profile = self.comboBox.currentIndex()+1

    def popup_buttonVideo(self, i):
        if i.text() == '&Yes':
            videotake(self.profile, self.camfourcc, self.cap, self.camFPS, self.camWidth, self.camHeight)
        else:
            self.cap.release()
            cv.destroyAllWindows()

    def popup_buttonAnalyze(self, i):
        if i.text() == 'Open':
            fname = QFileDialog.getOpenFileName(self, 'Open file', f'C:/Git/ELE3000/ELE3000_projet/Video/{self.profile}', 'Videos (*.mp4 *.avi)')
            self.filename = fname[0]
            self.erreur = 0
            if self.filename != '':
                self.erreur = analyzeVideo(self.filename, self.erreur)
            if self.erreur == 1:
                self.popup_erreur()


    def popup_buttonImage(self, i):
        if i.text() == 'Open':
            fname = QFileDialog.getOpenFileName(self, 'Open file', f'C:/Git/ELE3000/ELE3000_projet/Video/{self.profile}', 'Images (*.jpg *.png)')
            self.filename = fname[0]
            if self.filename != '':
                showImage(self.filename)

    def popup_erreur(self):
        msg4 = QMessageBox()
        msg4.setWindowTitle("Error")
        msg4.setText("There was an error analyzing the video")
        msg4.setStandardButtons(QMessageBox.Ok)
        msg4.setIcon(QMessageBox.Warning)
        x = msg4.exec_()
        


